import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.DFwwXrrM.js";const u=JSON.parse('{"title":"歌词体验","description":"","frontmatter":{},"headers":[],"relativePath":"guide/lyrics.md","filePath":"guide/lyrics.md","lastUpdated":null}'),r={name:"guide/lyrics.md"};function o(d,l,c,s,n,h){return e(),i("div",null,[...l[0]||(l[0]=[t('<h1 id="歌词体验" tabindex="-1">歌词体验 <a class="header-anchor" href="#歌词体验" aria-label="Permalink to &quot;歌词体验&quot;">​</a></h1><p>Still 的歌词能力覆盖普通歌词、翻译歌词、逐词歌词、全屏歌词和歌词复制。</p><h2 id="歌词来源" tabindex="-1">歌词来源 <a class="header-anchor" href="#歌词来源" aria-label="Permalink to &quot;歌词来源&quot;">​</a></h2><p>Still 支持两类歌词来源：</p><ul><li>内嵌歌词：从音频标签中读取</li><li>本地歌词：从音频文件同目录读取</li></ul><p>本地歌词支持：</p><ul><li>与歌曲同名的 <code>.lrc</code></li><li>与歌曲同名的 <code>.tlrc</code></li><li>与歌曲同名的 <code>.txt</code></li><li><code>lyrics.lrc</code></li></ul><h2 id="翻译与逐词" tabindex="-1">翻译与逐词 <a class="header-anchor" href="#翻译与逐词" aria-label="Permalink to &quot;翻译与逐词&quot;">​</a></h2><p>Still 会识别翻译歌词，并可在全屏歌词或桌面歌词中显示双语内容。</p><p>当歌词包含逐字时间轴时，可以开启逐词高亮，让当前播放文字按时间推进。</p><h2 id="全屏歌词模式" tabindex="-1">全屏歌词模式 <a class="header-anchor" href="#全屏歌词模式" aria-label="Permalink to &quot;全屏歌词模式&quot;">​</a></h2><p>全屏歌词支持四种模式：</p><ul><li>纯歌词</li><li>封面模式</li><li>横向混合</li><li>竖向混合</li></ul><p>可以调整歌词字号、翻译字号、字重、位置、左侧边距、滚动位置、模糊效果、淡出效果和远离视野效果。</p><h2 id="歌词偏移" tabindex="-1">歌词偏移 <a class="header-anchor" href="#歌词偏移" aria-label="Permalink to &quot;歌词偏移&quot;">​</a></h2><p>如果歌词和歌曲不同步，可以在全屏歌词中调整时间偏移。偏移范围为 <code>-5s</code> 到 <code>+5s</code>。</p><h2 id="复制歌词" tabindex="-1">复制歌词 <a class="header-anchor" href="#复制歌词" aria-label="Permalink to &quot;复制歌词&quot;">​</a></h2><p>复制歌词时可以选择要复制的行，也可以控制是否包含：</p><ul><li>翻译</li><li>音译</li><li>空行</li><li>歌名</li><li>歌手</li></ul>',19)])])}const _=a(r,[["render",o]]);export{u as __pageData,_ as default};
